let analyticsRequest=0;
async function renderAnalytics(){
  if(!$('#report-analytics'))return;const request=++analyticsRequest,from=$('#from').value,to=$('#to').value,category=$('#analytics-category').value,metric=$('#analytics-metric').value;
  try{const result=await api('/api/analytics?'+new URLSearchParams({from,to,category}));if(request!==analyticsRequest||!$('#report-analytics'))return;
    const gaps=state.coverage.filter(c=>!from||c.end.slice(0,10)>=from).filter(c=>!to||c.start.slice(0,10)<=to).flatMap(c=>M.coverageGaps(state,c));
    const unresolved=state.inspections.flatMap(i=>i.results).filter(r=>r.taskId&&state.tasks.find(t=>t.id===r.taskId)?.status!=='Completed').length;
    $('#report-analytics').innerHTML=`<div class="analytics-summary"><p><strong>${result.totalCompletions}</strong> recorded task completion events</p><p><strong>${gaps.length}</strong> coverage gap intervals in configured periods</p><p><strong>${state.inspections.length}</strong> saved inspections · <strong>${unresolved}</strong> unresolved corrective actions</p></div><h3>Completion history</h3>${table(['Date','Completion events'],result.completionEvents.map(r=>`<tr><td>${esc(r.date)}</td><td>${r.count}</td></tr>`))}<h3>Chemistry history</h3>${chemistryTrend(metric,from,to)}`;
    if(isSupervisor())await renderManagementAnalytics(request,from,to);
  }catch(error){if(request===analyticsRequest&&$('#report-analytics'))$('#report-analytics').textContent=error.message;}
}
function chemistryTrend(metric,from,to){
  const parameter=metric.startsWith('extra:')?(state.chemistryParameters||[]).find(p=>p.id===metric.slice(6)):null,value=r=>parameter?(r.additional||[]).find(x=>x.parameterId===parameter.id&&x.unit===parameter.unit)?.value:r[metric],label=parameter?.name||metric,unit=parameter?.unit||(metric==='temperature'?'°C':metric==='ph'?'':'ppm');
  const readings=state.chemistry.filter(r=>Number.isFinite(value(r))&&M.chemistryTimestamp(r)!==null&&(!from||localDay(new Date(M.chemistryTimestamp(r)))>=from)&&(!to||localDay(new Date(M.chemistryTimestamp(r)))<=to)).sort((a,b)=>M.chemistryTimestamp(a)-M.chemistryTimestamp(b));
  if(!readings.length)return '<p class="empty">No dated chemistry readings in this range.</p>';
  const points=readings.slice(-50),values=points.map(value),min=Math.min(...values),max=Math.max(...values),scale=Math.max(1,Math.abs(min),Math.abs(max)),coords=values.map((v,i)=>`${40+(values.length===1?220:i*440/(values.length-1))},${max===min?75:120-((v/scale-min/scale)/(max/scale-min/scale))*90}`).join(' ');
  return `<p class="muted">${esc(label)} · latest ${points.length} readings in range · recorded range ${min.toFixed(2)}–${max.toFixed(2)} ${esc(unit)}. Uses measurement time when entered; otherwise saved time.</p><svg class="chemistry-trend" viewBox="0 0 520 160" role="img" aria-label="${esc(label)} history for ${points.length} recorded readings"><title>${esc(label)} recorded history</title><path d="M40 20V130H490"/><polyline points="${coords}"/>${coords.split(' ').map(p=>{const [x,y]=p.split(',');return `<circle cx="${x}" cy="${y}" r="4"/>`;}).join('')}<text x="40" y="150">${esc(localDay(new Date(M.chemistryTimestamp(points[0]))))}</text><text x="390" y="150">${esc(localDay(new Date(M.chemistryTimestamp(points.at(-1)))) )}</text></svg><details><summary>View chart data</summary>${table(['Measured / saved','Saved to database','Value','User'],points.map(r=>`<tr><td>${esc(chemistryWhen(r))}</td><td>${esc(when(r))}</td><td>${value(r)}</td><td>${esc(r.createdBy||r.updatedBy||'Unknown')}</td></tr>`))}</details>`;
}
