function coverageMap(){
  const start=new Date((coverageDate||today())+'T00:00');start.setDate(start.getDate()-((start.getDay()+6)%7));
  const days=Array.from({length:7},(_,i)=>{const from=new Date(start);from.setDate(start.getDate()+i);const until=new Date(from);until.setDate(from.getDate()+1);const lower=localDay(from)+'T00:00',upper=localDay(until)+'T00:00',gapCount=state.coverage.filter(c=>c.start<upper&&c.end>lower).reduce((sum,c)=>sum+M.coverageGaps(state,{...c,start:c.start<lower?lower:c.start,end:c.end>upper?upper:c.end}).length,0);return {label:from.toLocaleDateString([],{weekday:'short'}),date:localDay(from),gapCount,count:state.shifts.filter(s=>new Date(s.start)<until&&new Date(s.end)>from).length};});
  const max=Math.max(1,...days.map(d=>d.count));
  return `<div class="calendar-box"><div class="coverage-controls">${button('coverage-week','','-7','‹')}<span>${esc(days[0].date)} – ${esc(days[6].date)}</span>${button('coverage-week','','7','›')}</div><div class="calendar-row">${days.map(d=>`<button type="button" data-action="coverage-day" data-id="${d.date}" title="${d.date}${d.gapCount?' · '+d.gapCount+' recorded staffing gap intervals':''}" aria-label="${esc(d.label+' '+d.date)}${d.gapCount?' · '+d.gapCount+' staffing gap intervals':''}" aria-pressed="${(coverageDate||today())===d.date}">${esc(d.label)}${d.gapCount?'<span class="coverage-gap-marker" aria-hidden="true">!</span>':''}</button>`).join('')}</div><div class="bars">${days.map((d,i)=>`<div class="coverage-row"><progress class="coverage-bar tone-${i%5}" max="${max}" value="${d.count}" aria-label="${esc(d.label+' '+d.date)}: ${d.count} scheduled shifts"></progress><span>${d.count}</span></div>`).join('')}</div><div class="coverage-detail">${coverageDayDetails(coverageDate||today())}</div></div>`;
}
const localDay=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function coverageDayDetails(date){const from=date+'T00:00',d=new Date(from);d.setDate(d.getDate()+1);const to=localDay(d)+'T00:00',rows=state.shifts.filter(s=>s.start<to&&s.end>from);return `<strong>${esc(date)} · ${rows.length} shifts</strong>${rows.map(s=>`<p>${esc(state.staff.find(p=>p.id===s.staffId)?.name)} · ${esc(s.start)}–${esc(s.end)} · ${esc(s.location)}</p>`).join('')}${state.coverage.filter(c=>c.start<to&&c.end>from).map(c=>{const gaps=M.coverageGaps(state,{...c,start:c.start<from?from:c.start,end:c.end>to?to:c.end});return `<p class="${gaps.length?'red-text':'green-text'}">${esc(c.location)}: ${gaps.length?'Staffing gap':'Configured coverage filled'}</p>${gaps.length&&isSupervisor()&&Date.parse(c.end)>Date.now()?`<p><a href="#recommendations" data-recommendation-target="coverage:${esc(c.id)}">Review replacements for ${esc(c.location)} →</a></p>`:''}`;}).join('')||'<p>No coverage requirement configured for this date.</p>'}`;}
function qualificationSummary(id){const q=M.currentQualifications(state,id);return q.length?q.slice(0,3).map(q=>`${esc(q.name)}${q.expiry<today()?' (expired)':''}`).join(', '):'No qualifications recorded';}
function scheduleAlerts(){return state.shifts.filter(s=>new Date(s.end)>new Date()).flatMap(s=>M.schedulingIssues(state,s.staffId,s).map(issue=>`<p class="alert">${esc(state.staff.find(p=>p.id===s.staffId)?.name)} · ${esc(s.start)} · ${esc(issue)}</p>`)).join('');}
function coverageDetails(){return table(['Coverage area','Gap interval','Qualified staff','Shortfall'],state.coverage.flatMap(c=>M.coverageGaps(state,c).map(g=>`<tr><td>${esc(c.location)}</td><td>${esc(g.start)} – ${esc(g.end)}</td><td>${g.assigned} / ${c.minimum}</td><td>${g.missing}</td></tr>`)));}
function approvalHistory(){return '<h3>Approved replacements</h3>'+table(['Approved','Supervisor','Employee','Shift'],[...state.assignments].reverse().map(a=>`<tr><td>${esc(when(a))}</td><td>${esc(a.actor)}</td><td>${esc(state.staff.find(p=>p.id===a.staffId)?.name||'Former employee')}</td><td>${esc(state.shifts.find(s=>s.id===a.shiftId)?.start||'Shift removed')}</td></tr>`));}
async function filePayload(file){if(!file||(!file.name&&!file.size))return null;if(!file.size)throw Error('The selected file is empty. Choose a nonempty file up to 5 MB.');if(file.size>5*1024*1024)throw Error('Choose a file up to 5 MB.');const bytes=new Uint8Array(await file.arrayBuffer());let text='';for(const b of bytes)text+=String.fromCharCode(b);return {name:file.name,base64:btoa(text)};}
function showTaskProgress(id){
  const task=state.tasks.find(t=>t.id===id),updates=state.taskupdates.filter(u=>u.taskId===id);$('#task-progress-panel')?.remove();
  const previous=updates.at(-1)?.completion,completion=task.status==='Completed'?100:['Scheduled','Confirmed'].includes(task.status)?0:previous>0&&previous<100?previous:'';
  const editor=canWrite('tasks')?`<p class="muted">The entered percentage updates task status: 0 Scheduled, 1–99 In Progress, 100 Completed. Review it when reopening or completing work. Task notes and new photos are shared with signed-in staff; supervisors can restrict photos in Documents. Put sensitive incident details in Incidents.</p><form data-kind="task-progress" data-id="${esc(id)}" class="editor"><label>Progress notes<textarea name="notes" required maxlength="10000"></textarea></label><label>Completion (%)<input name="completion" type="number" min="0" max="100" step="1" value="${completion}" required></label><label>Progress photo (optional, PNG/JPEG)<input name="file" type="file" accept=".png,.jpg,.jpeg"></label><button type="submit">Save progress</button></form>`:'';
  $('#content').insertAdjacentHTML('beforeend',`<div id="task-progress-panel">${card('Task progress: '+esc(task.name),editor+table(['Recorded','User','Completion','Notes','Photo'],[...updates].reverse().map(u=>`<tr><td>${esc(when(u))}</td><td>${esc(u.actor)}</td><td>${u.completion}%</td><td>${esc(u.notes)}</td><td>${u.fileId?`<a href="/api/files/${esc(u.fileId)}" target="_blank" rel="noopener">View progress photo</a>`:u.attachmentRestricted?'Supervisor-only photo':'—'}</td></tr>`)))}</div>`);$('#task-progress-panel').scrollIntoView({block:'start'});
}
async function showCandidates(id){AquaRecommendations.target='coverage:'+id;if(location.hash==='#recommendations')await AquaRecommendations.load();else location.hash='recommendations';}
function chemistryCheck(r){if(!state.thresholds.length&&!(state.chemistryParameters||[]).some(p=>p.active))return '<span class="muted">Facility limits not configured</span>';const alerts=M.chemistryAlerts(state,r);return alerts.length?`<span class="red-text">${alerts.some(a=>a.missing||a.unitMismatch)?'Review facility measurements':'Outside facility limits'}: ${alerts.map(a=>a.missing?`${esc(a.measurement)} not recorded`:a.unitMismatch?`${esc(a.measurement)} recorded in ${esc(a.unit)}, configured in ${esc(a.expectedUnit)}`:`${esc(a.measurement)} ${a.value} (${a.minimum}–${a.maximum})`).join('; ')}</span>`:'Within configured limits; not a compliance assessment';}
function chemistryTiming(){const timing=M.chemistryRecency(state);if(timing.future)return '<p class="red-text chemistry-timing">Reading timestamp is ahead of this workstation; review date/time before relying on it.</p>';if(!timing.configured)return '';return `<p class="chemistry-timing ${timing.overdue?'orange-text':'muted'}">${timing.missing?'No dated readings for the configured reminder.':timing.overdue?'Chemistry recording reminder overdue.':'Next chemistry recording reminder: '+esc(new Date(timing.dueAt).toLocaleString())+'.'} Facility interval: ${timing.interval} minutes; this is not a safety assessment.</p>`;}
function logFilterControls(){return `<div class="toolbar log-filters"><label>Search history<input id="log-search" type="search" value="${esc(logFilters.search)}"></label><label>From<input id="log-from" type="date" value="${esc(logFilters.from)}"></label><label>Through<input id="log-to" type="date" value="${esc(logFilters.to)}"></label></div>`;}
function logRows(){
  const matches=r=>{const timestamp=dashboardTab==='chemistry'?M.chemistryTimestamp(r):r.recordedAt,date=timestamp!==null&&timestamp!==undefined&&timestamp!==''?localDay(new Date(timestamp)):'';return (!logFilters.from||date>=logFilters.from)&&(!logFilters.to||(date&&date<=logFilters.to))&&JSON.stringify(r).toLowerCase().includes(logFilters.search.toLowerCase());};
  if(dashboardTab==='chemistry')return pagedTable('chemistry',['Time','Free Cl','pH','Temp','Alkalinity','Notes & details'],[...state.chemistry].reverse().filter(matches),r=>`<tr><td>${esc(M.chemistryTimestamp(r)===null?'Unknown date':new Date(M.chemistryTimestamp(r)).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}))}</td><td>${esc(r.chlorine)} ppm</td><td>${esc(r.ph)}</td><td>${esc(r.temperature)} °C</td><td>${esc(r.alkalinity)} ppm</td><td><details class="log-record-details"><summary>${esc(r.notes||'Reading details')}</summary><p>${esc(chemistryWhen(r))}</p><p>Saved: ${esc(when(r))} · ${esc(r.createdBy||'Unknown legacy author')}</p><p>${esc(additionalSummary(r))}</p><p>${chemistryCheck(r)}</p><div class="task-controls">${actions('chemistry',r)}</div></details></td></tr>`);
  if(dashboardTab==='safety')return table(['Recorded','Checklist','Recorded by','Results'],[...state.inspections].reverse().filter(matches).map(r=>`<tr><td>${esc(when(r))}</td><td>${esc(r.name)}</td><td>${esc(r.owner)}</td><td>${r.results.filter(i=>i.result==='Pass').length} passed · ${r.results.filter(i=>i.result==='Fail').length} failed</td></tr>`));
  if(!isSupervisor())return '<p>Incident records are restricted to supervisors.</p>';
  return recordTable('reports',state.reports.filter(r=>r.category==='Incident').reverse().filter(matches))+recordTable('incidents',[...state.incidents].reverse().filter(matches));
}
function certAlerts(){return M.currentQualifications(state).filter(q=>state.staff.find(p=>p.id===q.staffId)?.status!=='Inactive').map(q=>{const days=(Date.parse(q.expiry)-Date.parse(today()))/86400000;return days<=30?`<p class="alert">${esc(state.staff.find(p=>p.id===q.staffId)?.name)} · ${esc(q.name)} ${days<0?'expired':'expires within 30 days'} (${esc(q.expiry)})</p>`:'';}).join('');}
function inspectionSummary(){const failures=state.inspections.flatMap(i=>i.results).filter(r=>r.result==='Fail'&&state.tasks.find(t=>t.id===r.taskId)?.status!=='Completed').length;return `<p class="metric">${state.inspections.length?failures+' unresolved corrective actions':'Not assessed'}</p>${state.templates.map(t=>`<p>${esc(t.name)} · next due ${esc(t.nextDue)}${t.nextDue<today()?' · OVERDUE':t.nextDue===today()?' · DUE TODAY':''}</p>`).join('')||'<p>No checklists configured.</p>'}<a href="#inspections">Review inspections →</a>`;}
function uploadForm(){return canWrite('documents')?'<form data-kind="upload" class="editor"><label>Document title<input name="name" required maxlength="200"></label><label>Category<input name="category" required maxlength="100" list="document-categories"></label><datalist id="document-categories"><option>Procedures</option><option>Certifications</option><option>Inspection records</option><option>Incident records</option></datalist><label>Access<select name="access"><option>All staff</option><option>Supervisors</option></select></label><label>File<input name="file" type="file" accept=".pdf,.txt,.csv,.png,.jpg,.jpeg" required></label><button type="submit">Upload document</button></form>':'';}
function inspectionHistory(){
  if(!state.inspections.length)return '<p class="empty">No inspections recorded.</p>';
  return [...state.inspections].reverse().map(r=>`<details data-inspection="${esc(r.id)}"><summary>${esc(r.name)} · ${esc(when(r))} · ${esc(r.owner)}</summary>${table(['Check','Result','Notes','Corrective action'],r.results.map(item=>{const task=state.tasks.find(t=>t.id===item.taskId);return `<tr><td>${esc(item.label)}</td><td>${esc(item.result)}</td><td>${esc(item.notes)}</td><td>${item.taskId?esc(task?.status||'Missing corrective task')+' '+(task?button('progress','tasks',task.id,'Evidence / progress'):''):'—'}</td></tr>`;}))}<h3>Supporting evidence</h3><p class="muted">Files are appended with their recorded user and time; completed inspection results remain unchanged. Attach only necessary operational information.</p>${table(['Recorded','Added by','File','Description','Access'],state.documents.filter(d=>d.inspectionId===r.id).map(d=>`<tr><td>${esc(when(d))}</td><td>${esc(d.createdBy||'Unknown')}</td><td><a href="/api/files/${esc(d.fileId)}" target="_blank" rel="noopener">${esc(d.name)}</a> <a href="/api/files/${esc(d.fileId)}?download">Download evidence</a></td><td>${esc(d.evidenceNotes)}</td><td>${esc(d.access||'All staff')}</td></tr>`))}${canWrite('inspections')?`<form data-kind="inspection-evidence" data-id="${esc(r.id)}" class="editor"><label>File title<input name="name" required maxlength="200"></label><label>What this file supports<textarea name="notes" required maxlength="10000"></textarea></label>${isSupervisor()?'<label>Access<select name="access"><option>All staff</option><option>Supervisors</option></select></label>':''}<label>Evidence file<input name="file" type="file" accept=".pdf,.txt,.csv,.png,.jpg,.jpeg" required></label><button type="submit">Attach evidence</button></form>`:''}</details>`).join('');
}
async function loadSettings(){
  const accountForm=$('form[data-kind="account"]');if(accountForm&&!accountForm.querySelector('[name="staffId"]')){accountForm.querySelector('[name="role"]').insertAdjacentHTML('beforeend','<option>employee</option>');accountForm.querySelector('button').insertAdjacentHTML('beforebegin',staffBindingSelect(''));}
  if(accountForm)accountForm.previousElementSibling.textContent='Create individual accounts. Employee accounts require an explicit linked staff identity and have private portal access. Admin/manager/operator/viewer are trusted operational roles with broader shared visibility. Use Requests & Team for per-employee recording permissions.';
  if(user.role==='admin'){const users=await api('/api/users');if($('#accounts'))$('#accounts').innerHTML=table(['User','Name','Role','Access','Actions'],users.map(u=>`<tr><td>${esc(u.username)}</td><td>${esc(u.name)}</td><td>${esc(u.role)}</td><td>${u.active?'Enabled':'Disabled'}</td><td>${u.id!==user.id?button('account',u.role,u.id,u.active?'Manage / disable':'Manage / enable'):''}</td></tr>`));}
  if($('#audit')){if(!['admin','manager'].includes(user.role)){$('#audit').textContent='Manager access required.';return;}const audit=await api('/api/audit');if($('#audit'))$('#audit').innerHTML=table(['When','User','Action'],audit.map(a=>`<tr><td>${esc(a.at)}</td><td>${esc(a.actor)}</td><td>${esc(a.action)}</td></tr>`));}
  if(user.role==='admin'&&location.hash==='#settings'){if(!$('#full-backups'))$('#content').insertAdjacentHTML('beforeend',card('Full Local Recovery Snapshots','<p>Includes accounts, private employee history, permissions, audit, documents and records. Snapshots stay in this workspace’s backups folder; arrange protected off-device copies and rehearse recovery. Browser JSON export is only an operational merge.</p><button type="button" data-portal-action="create-full-backup">Create full local snapshot</button><div id="full-backups">Loading snapshots…</div>'));await AquaPortal.loadBackups();}
}
function inspectionForm(){const t=state.templates.find(t=>t.id===$('#inspection-template').value);$('#inspection-form').innerHTML=t?`<form data-kind="inspection" data-id="${esc(t.id)}" class="editor">${t.items.split(/\r?\n/).map((label,i)=>`<fieldset><legend>${esc(label)}</legend><label>Result<select name="result-${i}" required><option value="">Select result</option><option>Pass</option><option>Fail</option><option>Not applicable</option></select></label><label>Notes (required for failures)<input name="notes-${i}" maxlength="10000"></label></fieldset>`).join('')}<label>Corrective action owner<select name="owner"><option value="">Unassigned</option>${state.staff.map(p=>`<option>${esc(p.name)}</option>`).join('')}</select></label><label>Corrective action due (if failures)<input type="date" name="due"></label><label>Next inspection due<input type="date" name="nextDue" required></label><button type="submit">Save inspection</button></form>`:'';}
function filteredReports(){
  const cat=$('#report-filter').value,from=$('#from').value,to=$('#to').value;
  if(from&&to&&from>to){notice('From date must be on or before through date.');return [];}
  const reports=state.reports.map(r=>({...r,source:'reports'}));
  reports.push(...state.incidents.map(r=>({...r,source:'incidents',category:'Incident',owner:r.createdBy||r.updatedBy,notes:`${r.location}; ${r.severity}; ${r.status}; ${r.description}; ${r.response}`})));
  reports.push(...state.adjustments.map(r=>({...r,source:'adjustments',category:'Inventory',title:'Stock change: '+r.name,owner:r.actor||'Legacy user unknown',notes:`${r.delta>0?'+':''}${r.delta} ${r.unit||'(legacy unit unknown)'}; ${r.reason}`})));
  reports.push(...state.inspections.map(r=>({...r,source:'inspections',category:'Inspection',title:r.name,notes:r.results.map(i=>`${i.label}: ${i.result} ${i.notes}`).join('\n')})));
  for(const kind of ['chemistry','tasks','inventory','equipment'])reports.push(...state[kind].map(r=>({id:r.id,source:kind,recordedAt:sourceTime(kind,r),legacyTime:r.legacyTime||'Unknown date',category:{chemistry:'Chemistry',tasks:'Tasks',inventory:'Inventory',equipment:'Equipment'}[kind],title:r.name||'Water chemistry',owner:r.owner||r.createdBy||r.updatedBy||'',notes:kind==='chemistry'?`Free Cl ${r.chlorine} ppm; pH ${r.ph}; ${r.temperature} °C; alkalinity ${r.alkalinity} ppm; ${r.notes}; ${chemistryWhen(r)}; Saved to database: ${when(r)}`:kind==='inventory'?`${r.quantity} ${r.unit}; restock at ${r.threshold}`:kind==='tasks'?`${r.status}; ${r.category}; due ${r.due||'unset'}`:`${r.status}; ${r.notes}`})));
  const chemistryById=new Map(state.chemistry.map(r=>[r.id,r]));for(const r of reports)if(r.source==='chemistry'){const extra=additionalSummary(chemistryById.get(r.id));if(extra)r.notes+='; '+extra;}
  return reports.filter(r=>{const d=new Date(r.recordedAt),date=r.recordedAt?`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`:'';return(cat==='All'||r.category===cat)&&(!from||(date&&date>=from))&&(!to||(date&&date<=to));}).sort((a,b)=>(Date.parse(b.recordedAt)||0)-(Date.parse(a.recordedAt)||0));
}
function renderResults(){
  if(!$('#results'))return;const page=location.hash.slice(1);
  if(page==='reports'){$('#results').innerHTML=pagedTable('report-results',['Recorded','Category','Title','Recorded by','Details','Actions'],filteredReports(),r=>`<tr><td>${esc(when(r))}</td><td>${esc(r.category)}</td><td>${esc(r.title)}</td><td>${esc(r.owner)}</td><td>${esc(r.notes)}</td><td>${r.source==='reports'?actions('reports',r):'<span class="muted">Generated from source record</span>'}</td></tr>`);return;}
  const rows=page==='tasks'?state.tasks.filter(t=>($('#task-filter').value==='All'||t.status===$('#task-filter').value)&&($('#task-category').value==='All'||t.category===$('#task-category').value)&&`${t.name} ${t.owner}`.toLowerCase().includes($('#task-search').value.toLowerCase())):listFilters[page]?filteredRecords(page):state[page];$('#results').innerHTML=recordTable(page,rows);
}
async function submitForm(e){
  const f=e.target.closest('form[data-kind]');if(!f)return;e.preventDefault();
  if(busy)return;
  if(user&&f.dataset.kind!=='pattern-preview'&&hasUnsavedChanges(f)&&!confirm('Saving this record will replace this view and discard unsaved entries in other forms. Continue?'))return;
  busy=true;const submit=f.querySelector('[type="submit"]');if(submit)submit.disabled=true;
  try{
  const kind=f.dataset.kind,data=Object.fromEntries(new FormData(f));
  Object.keys(data).forEach(k=>{if(typeof data[k]==='string'&&!['password','current'].includes(k))data[k]=data[k].trim();});
  if(['login','setup'].includes(kind)){const session=await api('/api/'+kind,'POST',data);await signedIn(session);notice('Signed in.');return;}
  if(kind.startsWith('portal-')){await AquaPortal.submit(kind.slice(7),data,f);return;}
  if(kind==='account'){await api('/api/users','POST',data);f.reset();await loadSettings();notice('Account created.');return;}
  if(kind==='account-update'){await api('/api/users/'+f.dataset.id,'PATCH',{role:data.role,active:data.active==='true',staffId:data.staffId,password:data.password,version:f.dataset.version});render();notice('Account updated; its sessions have been revoked.');return;}
  if(kind==='password'){const session=await api('/api/password','POST',data);await signedIn(session);notice('Password changed; previous sessions revoked.');return;}
  if(kind==='quick-task'){await mutate('/api/records/tasks','POST',{record:{name:data.name,status:'Scheduled',priority:'Normal',due:'',owner:'',category:'Maintenance'}});return;}
  if(kind==='pattern-preview'){
    const fingerprint=JSON.stringify([...new FormData(f)]),pattern={...data,weekdays:new FormData(f).getAll('weekdays').map(Number),...(data.type==='Coverage'?{minimum:Number(data.minimum)}:{})},expectedRevision=revision;
    const plan=await api('/api/schedule/preview','POST',{pattern,revision:expectedRevision});if(!f.isConnected)return;if(JSON.stringify([...new FormData(f)])!==fingerprint)throw Error('Pattern changed while the preview loaded. Preview it again before applying.');patternDraft={pattern,plan,revision:expectedRevision};$('#pattern-preview').innerHTML=patternPreview(plan);return;
  }
  if(kind==='task-progress'){const id=f.dataset.id;await mutate('/api/tasks/'+id+'/progress','POST',{notes:data.notes,completion:Number(data.completion),file:await filePayload(data.file)});showTaskProgress(id);return;}
  if(kind==='inspection-evidence'){const id=f.dataset.id;await mutate('/api/inspections/'+id+'/evidence','POST',{name:data.name,notes:data.notes,access:data.access||'All staff',file:await filePayload(data.file)});const details=$(`[data-inspection="${id}"]`);if(details){details.open=true;details.scrollIntoView({block:'start'});}return;}
  if(kind==='upload'){
    const file=data.file;if(!file||file.size>5*1024*1024)throw Error('Choose a file up to 5 MB.');
    const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);
    await mutate('/api/documents/upload','POST',{name:data.name,category:data.category,access:data.access,file:{name:file.name,base64:btoa(binary)}});return;
  }
  if(kind==='inspection'){const t=state.templates.find(t=>t.id===f.dataset.id);await mutate('/api/inspections','POST',{templateId:t.id,results:t.items.split(/\r?\n/).map((_,i)=>({result:data['result-'+i],notes:data['notes-'+i]})),owner:data.owner,due:data.due,nextDue:data.nextDue});return;}
  if(kind==='adjustment'){
    await mutate('/api/inventory/'+f.dataset.id+'/adjust','POST',{delta:Number(data.delta),reason:data.reason});
  }else{
    if(kind==='chemistry')data.additional=collectAdditional(data,state.chemistryParameters);
    for(const [k,[,type,required]] of Object.entries(M.schemas[kind]))if(type==='number'&&data[k]!==undefined&&(data[k]!==''||required))data[k]=Number(data[k]);
    const result=await mutate('/api/records/'+kind+(f.dataset.id?'/'+f.dataset.id:''),f.dataset.id?'PUT':'POST',{record:data});if(kind==='incidents'&&user.role==='operator')notice('Saved confidential incident. Reference: '+result.reference+'. Only supervisors can review it; no external notification was sent.');
  }
  }catch(error){notice(error.message+(f.isConnected?' Your form is kept. If the connection failed, refresh and check for a saved record before retrying.':''));}
  finally{busy=false;if(submit?.isConnected)submit.disabled=false;}
}
document.addEventListener('submit',submitForm);
document.addEventListener('change',e=>{if(['task-filter','task-category','report-filter','from','to'].includes(e.target.id))renderResults();if(e.target.id==='inspection-template')inspectionForm();if(['from','to','analytics-category','analytics-metric'].includes(e.target.id))renderAnalytics();});
document.addEventListener('input',e=>{if(e.target.id==='task-search')renderResults();if(e.target.closest('form[data-kind="pattern-preview"]'))invalidatePattern();if(['log-search','log-from','log-to'].includes(e.target.id)){logFilters[{ 'log-search':'search','log-from':'from','log-to':'to'}[e.target.id]]=e.target.value;$('#log-results').innerHTML=logRows();}});
document.addEventListener('input',e=>{const key={'schedule-from':'from','schedule-through':'through','schedule-employee':'staffId','schedule-search':'search'}[e.target.id];if(key&&scheduleFilters[key]!==e.target.value){scheduleFilters[key]=e.target.value;renderSchedule();}});
document.addEventListener('change',e=>{const key={'schedule-from':'from','schedule-through':'through','schedule-employee':'staffId'}[e.target.id];if(key&&scheduleFilters[key]!==e.target.value){scheduleFilters[key]=e.target.value;renderSchedule();}});
for(const event of ['input','change'])document.addEventListener(event,e=>{const page=e.target.dataset.listFilter;if(page&&listFilters[page]&&listFilters[page][e.target.name]!==e.target.value){listFilters[page][e.target.name]=e.target.value;renderResults();}});
document.addEventListener('change',e=>{if(e.target.closest('form[data-kind="pattern-preview"]')){invalidatePattern();syncPatternFields();}});
document.addEventListener('change',e=>{if(['log-from','log-to'].includes(e.target.id)){const key=e.target.id==='log-from'?'from':'to';if(logFilters[key]!==e.target.value){logFilters[key]=e.target.value;$('#log-results').innerHTML=logRows();}}});
document.addEventListener('change',async e=>{
  const id=e.target.dataset.taskStatus;if(!id)return;const task=state.tasks.find(t=>t.id===id);
  if(hasUnsavedChanges()&&!confirm('Changing task status will replace this view and discard unsaved form entries. Continue?')){e.target.value=task.status;return;}
  if(busy){e.target.value=task.status;return;}busy=true;e.target.disabled=true;
  try{await mutate('/api/records/tasks/'+id,'PUT',{record:{...task,status:e.target.value}});}catch(error){e.target.value=task.status;notice(error.message);}finally{busy=false;if(e.target.isConnected)e.target.disabled=false;}
});
async function clickAction(e){
  const b=e.target.closest('[data-action]');if(!b)return;const {action,kind,id}=b.dataset;
  if(busy)return;busy=true;b.disabled=true;
  try{
  if(action==='table-page')turnTablePage(kind,Number(id));
  if(['edit','cancel','starter','coverage-day','coverage-week','log-tab','schedule-clear','logout','toggle','approve','delete','account'].includes(action)&&hasUnsavedChanges()&&!confirm('Continue and discard unsaved form entries?'))return;
  if(action==='progress'&&$('#task-progress-panel form')&&formHasChanges($('#task-progress-panel form'))&&!confirm('Open task progress and discard the unfinished progress entry?'))return;
  if(action==='log-tab'){dashboardTab=kind;editing=null;render();$(`[data-action="log-tab"][data-kind="${kind}"]`).focus();}
  if(action==='coverage-day'){coverageDate=id;render();}
  if(action==='coverage-week'){const d=new Date((coverageDate||today())+'T12:00');d.setDate(d.getDate()+Number(id));coverageDate=localDay(d);render();}
  if(action==='planner-scroll')$('#staff-planner').scrollIntoView({block:'start'});
  if(action==='schedule-clear'){scheduleFilters={from:'',through:'',staffId:'',search:''};render();}
  if(action==='schedule-csv'){const rows=M.filterShifts(state,scheduleFilters);exportCsv('aquaops-schedule-'+today()+'.csv',['Employee','Role','Start (facility local)','End (facility local)','Coverage area','Required certifications','Current assignment review'],rows.map(s=>{const p=state.staff.find(p=>p.id===s.staffId);return [p?.name,p?.role,s.start,s.end,s.location,s.requirements,M.schedulingIssues(state,s.staffId,s).join('; ')||'No recorded conflict'];}));}
  if(action==='apply-pattern'){
    if(!patternDraft)throw Error('Preview the current pattern before applying it.');const draft=patternDraft;
    if(confirm('Apply these previewed dated records? Existing rows will be preserved. Review any availability conflicts before approving.')){await mutate('/api/schedule/apply','POST',{pattern:draft.pattern},draft.revision);notice('Saved the weekly pattern. Existing dated records were preserved.');}
  }
  if(action==='progress')showTaskProgress(id);
  if(action==='candidates')await showCandidates(id);
  if(action==='approve'&&confirm('Approve this employee as the replacement for the complete coverage period?'))await mutate('/api/coverage/'+kind+'/assign','POST',{staffId:id});
  if(action==='starter'){
    editing=null;render();const f=$('form[data-kind="templates"]');f.elements.name.value=kind==='opening'?'Opening inspection':'Closing inspection';f.elements.items.value=kind==='opening'?'Review facility opening status and restrictions\nReview recorded chemistry against facility procedures\nCheck rescue equipment and deck condition\nConfirm assigned staff and qualifications':'Record final chemistry and operating observations\nCheck equipment shutdown against facility procedures\nReview incidents and unresolved corrective tasks\nSecure the facility and hand over outstanding work';f.elements.nextDue.value=today();f.scrollIntoView({block:'center'});f.elements.name.focus();notice('Starter draft loaded. Review and customize before saving; it is not a regulatory checklist.');
  }
  if(action==='refresh'){if(confirm('Refresh records? Unsaved form entries will be discarded.')){await refresh();editing=null;render();notice('Latest facility data loaded.');}}
  if(action==='logout'){await api('/api/logout','POST',{});state=M.blank();authScreen(false);notice('Signed out.');}
  if(action==='password')$('#password-form').innerHTML='<form data-kind="password" class="editor"><label>Current password<input name="current" type="password" required autocomplete="current-password"></label><label>New password<input name="password" type="password" required minlength="12" maxlength="256" autocomplete="new-password"></label><button type="submit">Save password</button></form>';
  if(action==='account'){const users=await api('/api/users'),target=users.find(u=>u.id===id);$('form[data-kind="account-update"]')?.remove();$('#accounts').insertAdjacentHTML('beforeend',`<form data-kind="account-update" data-id="${esc(id)}" data-version="${esc(target.version)}" class="editor"><strong>${esc(target.username)}</strong><label>Role<select name="role">${['admin','manager','operator','viewer'].map(r=>`<option ${r===target.role?'selected':''}>${r}</option>`).join('')}</select></label><label>Access<select name="active"><option value="true">Enabled</option><option value="false" ${!target.active?'selected':''}>Disabled</option></select></label><label>Reset password (optional)<input name="password" type="password" minlength="12" maxlength="256" autocomplete="new-password"></label><button type="submit">Update account</button></form>`);}
  if(action==='edit'){if(kind==='shifts'&&location.hash==='#schedule')history.replaceState(null,'','#staff');editing={kind,id};render();const target=$(`form[data-kind="${kind}"]`);target?.scrollIntoView({block:'start'});target?.querySelector('input,select')?.focus();}
  if(action==='account'){const target=(await api('/api/users')).find(u=>u.id===id),f=$('form[data-kind="account-update"]');f.querySelector('[name="role"]').insertAdjacentHTML('beforeend',`<option ${target.role==='employee'?'selected':''}>employee</option>`);f.querySelector('button').insertAdjacentHTML('beforebegin',staffBindingSelect(target.staffId));}
  if(action==='cancel'){editing=null;render();}
  if(action==='delete'&&confirm('Delete this record? Its previous value remains in the server change history.'))await mutate('/api/records/'+kind+'/'+id,'DELETE',{});
  if(action==='toggle'){const t=state.tasks.find(t=>t.id===id);await mutate('/api/records/tasks/'+id,'PUT',{record:{...t,status:t.status==='Completed'?'Scheduled':'Completed'}});}
  if(action==='adjust'){$('#adjustment').innerHTML=`<form data-kind="adjustment" data-id="${esc(id)}" class="editor"><label>Quantity change (negative to consume)<input name="delta" type="number" step="any" required></label><label>Reason<input name="reason" required maxlength="200"></label><button type="submit">Save adjustment</button></form>`;$('#adjustment input').focus();}
  if(action==='csv'){
    exportCsv('aquaops-reports.csv',['Recorded','Category','Title','Recorded by','Details'],filteredReports().map(r=>[r.recordedAt,r.category,r.title,r.owner,r.notes]));
  }
  }catch(error){notice(error.message);}finally{busy=false;if(b.isConnected)b.disabled=false;}
}
document.addEventListener('click',clickAction);
$('.skip').addEventListener('click',e=>{e.preventDefault();$('#content').focus();});
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function formHasChanges(form){
  return [...form.elements].some(field=>{
    if(!field.name||field.disabled||['submit','button','hidden'].includes(field.type))return false;
    if(field.type==='file')return field.files.length>0;
    if(['checkbox','radio'].includes(field.type))return field.checked!==field.defaultChecked;
    if(field.tagName==='SELECT'){const defaults=[...field.options].filter(option=>option.defaultSelected);const original=defaults.length?defaults.map(option=>option.value):field.multiple?[]:[field.options[0]?.value];return JSON.stringify([...field.selectedOptions].map(option=>option.value))!==JSON.stringify(original);}
    return field.value!==field.defaultValue;
  });
}
function hasUnsavedChanges(exceptForm){return [...document.querySelectorAll('form[data-kind]')].some(form=>form!==exceptForm&&formHasChanges(form));}
function exportCsv(name,headers,rows){const cell=v=>{let s=String(v??'');if(/^\s*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};download(name,'\ufeff'+[headers,...rows].map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
$('#backup').onclick=async()=>{try{download(`aquaops-${today()}.json`,JSON.stringify(await api('/api/backup'),null,2),'application/json');}catch(e){notice(e.message);}};
$('#restore').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>32*1024*1024)throw Error('Backup too large for browser import. Use the offline database backup.');const data=JSON.parse(await file.text());M.upgrade(data.state||data);if(confirm('Merge records and files from this backup? Conflicting IDs will cancel the entire import; existing records will not be replaced.'))await mutate('/api/import','POST',{state:data.state||data,files:data.files||[]});}catch(err){notice(`Backup not imported: ${err.message}`);}finally{e.target.value='';}};
$('#legacy').onclick=async()=>{try{const raw=localStorage.getItem(KEY),oldTasks=localStorage.getItem('aquaopsTasksV2'),oldReadings=localStorage.getItem('aquaopsChemistry');if(raw===null&&oldTasks===null&&oldReadings===null)throw Error('No legacy workspace was found in this browser at this address. Use the original browser/address or import its backup.');const legacy=raw!==null?M.upgrade(JSON.parse(raw)):M.migrate(JSON.parse(oldTasks||'null'),JSON.parse(oldReadings||'null'));if(Object.values(legacy).filter(Array.isArray).every(rows=>!rows.length))throw Error('The legacy workspace contains no records to import.');if(confirm('Merge this browser’s legacy data into the facility database? Original browser storage will be preserved.'))await mutate('/api/import','POST',{state:legacy});}catch(e){notice('Legacy data not imported: '+e.message);}};
window.addEventListener('hashchange',async e=>{if(user&&hasUnsavedChanges()&&!confirm('Leave this page and discard unsaved form entries?')){history.replaceState(null,'',e.oldURL);return;}const epoch=sessionEpoch,target=location.hash;if($('#message').classList.contains('message-success'))notice('');editing=null;try{if(user&&user.role!=='employee'){$('#content').innerHTML=card('Loading','Loading latest facility records…');await refresh();if(epoch!==sessionEpoch||target!==location.hash)return;}render();$('#content').focus();}catch(error){if(epoch===sessionEpoch)notice(error.message);}});
window.addEventListener('beforeunload',e=>{if(user&&hasUnsavedChanges()){e.preventDefault();e.returnValue='';}});
window.addEventListener('focus',checkSession);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkSession();});
setInterval(()=>{if(!document.hidden)checkSession();},60000);
boot();
